%[text] %[text:anchor:H_733CD629] # Convergence study on transverse shear-locking
%[text:tableOfContents]{"heading":"Table of Contents"}
%[text] In this section it is shown how the rate of the mesh convergence study is reduced down due to transverse shear locking. The effect gets more pronounced with increased slenderness of the beam.
%[text] 
%[text] Go to [THIS](file:.\main_Chapter6_HellingerReissnerFormulation_TimoshenkoBeam_Study.m) Section in the main driver script *Transverse-shear locking due incompatible discretization spaces*
%[text] Go to [PREVIOUS](file:.\main_Chapter61_HellingerReissnerTimoshenko_ShearForces.m) Section *Transverse-shear locking due incompatible discretization spaces*
%[text] 
%[text] **Author: Andreas Apostolatos, PhD (aapostol@mathworks.com)**
%[text] **Date: 10.06.2026**
%%
%[text] %[text:anchor:H_7236A159] ## Preamble
vars = ["numEl" "wEx" "X0" "XL" "choiceShapeFunctionsU" ...
    "choiceShapeFunctionsLM" "propStr" ...
    "computeBasisFunctionsAndDerivsHRU"];
str = "This m-file should be ran from parent m-file " + ...
    "main_Chapter6_HellingerReissnerFormulation_TimoshenkoBeam_Study.m";
for ii = 1:length(vars)
    if ~exist(vars(ii), 'var') 
        error(strcat("Variable ", vars(ii), " is not defined. ", str));
    end
end
%%
%[text] %[text:anchor:H_228A28A6] ## Initialize auxiliary arrays
wAnalytical = double(wEx(XL));
tipDeflection = zeros(numEl, 5);
numElmnts = zeros(numEl, 1);
tipDeflectionAnalytical = repmat(wAnalytical, numEl, 1);
%%
%[text] %[text:anchor:H_707313A0] ## Loop over all the refinement levels
for ii = 1:numEl
%[text] %[text:anchor:H_B515668C] ### **One-dimensional linear mesh**
    numElmnts(ii, 1) = ii; % number of elements
    mshL1Ref = generateLinearMeshOnLine(X0, XL, numElmnts(ii, 1));
    numNodesL1Ref = numel(mshL1Ref.nodes(:, 1));
%[text] %[text:anchor:H_35714E1E] ### One-dimensional quadratic mesh
    mshL2Ref = generateQuadraticMeshOnLine(mshL1Ref);
    numNodesL2Ref = numel(mshL2Ref.nodes(:, 1));
%[text] %[text:anchor:H_32697513] ### Mesh used for the discretization Lagrange Multipliers field in the frame of the Hellinger-Reissner principle
    switch choiceShapeFunctionsU
        case 1
            mshHRRef = mshL1Ref;
        case 2
            mshHRRef = mshL2Ref;
    end
%[text] %[text:anchor:H_13138FCB] ### Dirichlet boundary conditions for the **one-dimensional linear mesh**
    numDOFsL1Ref = 2*numNodesL1Ref;
    freeDOFsL1Ref = 1:numDOFsL1Ref;
    homDOFsL1Ref = 1:2;
    [~, idxL1Ref] = ismember(homDOFsL1Ref, freeDOFsL1Ref);
    freeDOFsL1Ref(idxL1Ref) = [];
%[text] %[text:anchor:H_B9418267] ### Dirichlet boundary conditions for the one-dimensional quadratic mesh
    numDOFsL2Ref = 2*numNodesL2Ref;
    freeDOFsL2Ref = 1:numDOFsL2Ref;
    homDOFsL2Ref = 1:2;
    [~, idxL2Ref] = ismember(homDOFsL2Ref, freeDOFsL2Ref);
    freeDOFsL2Ref(idxL2Ref) = [];
%[text] %[text:anchor:H_791ADC76] ### Number of nodes, number of DOFs and free DOFs for the Timoshenko beam formulation using the Hellinger-Reissner principle
    switch choiceShapeFunctionsU
        case 1
            numNodesHRRef = numNodesL1Ref;
            numDOFsHRRef = numDOFsL1Ref;
            freeDOFsHRRef = homDOFsL1Ref;
        case 2
            numNodesHRRef = numNodesL2Ref;
            numDOFsHRRef = numDOFsL2Ref;
            freeDOFsHRRef = freeDOFsL2Ref;
    end
%[text] %[text:anchor:H_E13F272D] ### Master stiffness matrix and load vector for  the one-dimensional linear mesh using full-integration
    computeBasisFunctionsAndDerivsU = ...
        @computeLinearBasisFunctionsAndFirstDerivatives;
    computeStiffMatrixandForceVector = 'undefined';
    computeBasisFunctionsAndDerivsBeta = 'undefined';
    [KL1Ref, FBodyL1Ref] = ...
        computeMasterStiffMatrixandForceVectorTimoshenkoBeamPageWise ...
        (mshL1Ref, computeStiffMatrixandForceVector, ...
        computeBasisFunctionsAndDerivsU, computeBasisFunctionsAndDerivsBeta, ...
        propStr);
    FL1BoundaryRef = zeros(2*numNodesL1Ref, 1);
    FL1BoundaryRef(end - 1, 1) = propStr.Q;
    FL1BoundaryRef(end, 1) = propStr.M;
    FL1Ref = FBodyL1Ref + FL1BoundaryRef;
%[text] %[text:anchor:H_7A8A870D] ### Master stiffness matrix and load vector for the one-dimensional linear mesh using selective-reduced integration
    computeBasisFunctionsAndDerivsU = ...
        @computeLinearBasisFunctionsAndFirstDerivatives;
    computeStiffMatrixandForceVectorRI = 'undefined';
    computeBasisFunctionsAndDerivsBeta = 'undefined';
    [KL1RIRef, FBodyL1RIRef] = ...
        computeMasterStiffMatrixandForceVectorTimoshenkoBeamRIPageWise ...
        (mshL1Ref, computeStiffMatrixandForceVectorRI, ...
        computeBasisFunctionsAndDerivsU, computeBasisFunctionsAndDerivsBeta, ...
        propStr);
    FL1BoundaryRIRef = zeros(2*numNodesL1Ref, 1);
    FL1BoundaryRIRef(end - 1, 1) = propStr.Q;
    FL1BoundaryRIRef(end, 1) = propStr.M;
    FL1RIRef = FBodyL1RIRef + FL1BoundaryRIRef;
%[text] %[text:anchor:H_980DF099] ### Master stiffness matrix and load vector for the one-dimensional quadratic mesh using full-integration
    computeBasisFunctionsAndDerivsU = ...
        @computeQuadraticBasisFunctionsAndFirstDerivatives;
    computeStiffMatrixandForceVector = 'undefined';
    computeBasisFunctionsAndDerivsBeta = 'undefined';
    [KL2Ref, FBodyL2Ref] = ...
        computeMasterStiffMatrixandForceVectorTimoshenkoBeamPageWise ...
        (mshL2Ref, computeStiffMatrixandForceVector, ...
        computeBasisFunctionsAndDerivsU, computeBasisFunctionsAndDerivsBeta, ...
        propStr);
    FBoundaryL2Ref = zeros(2*numNodesL2Ref, 1);
    FBoundaryL2Ref(2*numNodesL1Ref - 1, 1) = propStr.Q;
    FBoundaryL2Ref(2*numNodesL1Ref, 1) = propStr.M;
    FL2Ref = FBodyL2Ref + FBoundaryL2Ref;
%[text] %[text:anchor:H_27974968] ### Master stiffness matrix and load vector for the one-dimensional mesh using the Hellinger-Reissner formulation and the full-integration
    computeStiffMatrixandForceVector = ...
        @computeElStiffMtxForceVctHellingerReissnerTimoshenkoBeam;
    [KHRRef, FBodyHRRef] = computeMasterStiffMatrixandForceVectorTimoshenkoBeam ...
        (mshHRRef, computeStiffMatrixandForceVector, ...
        computeBasisFunctionsAndDerivsHRU, computeBasisFunctionsAndDerivsLM, ...
        propStr);
    FHRBoundaryRef = zeros(2*numNodesHRRef, 1);
    FHRBoundaryRef(end - 1, 1) = propStr.Q;
    FHRBoundaryRef(end, 1) = propStr.M;
    FHRRef = FBodyHRRef + FHRBoundaryRef;
%[text] %[text:anchor:H_F6EA2C4E] ### Master stiffness matrix and load vector using the Euler-Bernoulli beam theory and the cubic Hermitian basis functions
    computeStiffMatrixandForceVectorEBT = ...
        @computeElementStiffMatrixandForceVectorEulerBernoulliBeam;
    [KEBRef, FBodyEBRef] = ...
        computeMasterStiffMatrixandForceVectorEulerBernoulliBeam ...
        (mshL1Ref, computeStiffMatrixandForceVectorEBT, propStrEB);
    FBoundaryEBRef = zeros(2*numNodesL1Ref, 1);
    FBoundaryEBRef(end - 1, 1) = propStr.Q;
    FBoundaryEBRef(end, 1) = - propStr.M;
    FEBRef = FBodyEBRef + FBoundaryEBRef;
%[text] %[text:anchor:H_CBA452D8] ### Initialization of the solution vectors
    uL1Ref = zeros(numDOFsL1Ref, 3);
    uL2Ref = zeros(numDOFsL2Ref, 2);
    uHRRef = zeros(numDOFsHRRef, 1);
%[text] %[text:anchor:H_83C9C772] ### Solution of the linear equation system corresponding to the one-dimensional linear mesh using full-integration
    uL1Ref(freeDOFsL1Ref, 1) = ...
        KL1Ref(freeDOFsL1Ref, freeDOFsL1Ref)\FL1Ref(freeDOFsL1Ref);
    tipDeflection(ii, 1) = uL1Ref(end - 1, 1);
%[text] %[text:anchor:H_23654F7E] ### Solution of the linear equation system corresponding to the one-dimensional linear mesh using selective-reduced integration
    uL1Ref(freeDOFsL1Ref, 2) = ...
        KL1RIRef(freeDOFsL1Ref, freeDOFsL1Ref)\FL1RIRef(freeDOFsL1Ref);
    tipDeflection(ii, 2) = uL1Ref(end - 1, 2);
%[text] %[text:anchor:H_F3B83EBB] ### Solution of the linear equation system corresponding to the one-dimensional quadratic mesh using full-integration
    uL2Ref(freeDOFsL2Ref, 1) = ...
        KL2Ref(freeDOFsL2Ref, freeDOFsL2Ref)\FL2Ref(freeDOFsL2Ref);
    [~, idxRef] = sort(mshL2Ref.nodes);
    wL2Ref = uL2Ref(1:2:end, 1);
    tipDeflection(ii, 3) = wL2Ref(idxRef(end), 1);
%[text] %[text:anchor:H_DAE7FF8A] ### Solution of the linear equation system corresponding to the Timoshenko Finite Element formulation using the Hellinger-Reissner principle
    uHRRef(freeDOFsL1Ref, 1) = ...
        KHRRef(freeDOFsL1Ref, freeDOFsL1Ref)\FHRRef(freeDOFsL1Ref);
    tipDeflection(ii, 4) = uHRRef(end - 1, 1);
%[text] %[text:anchor:H_67D5AB33] ### Solution of the linear equation system corresponding to the Euler-Bernoulli beam theory
    uL1Ref(freeDOFsL1Ref, 3) = KEBRef(freeDOFsL1Ref, freeDOFsL1Ref)\FEBRef(freeDOFsL1Ref);
    tipDeflection(ii, 5) = uL1Ref(end - 1, 3);    
%[text] 
end
%%
%[text] %[text:anchor:H_F41A9C84] ## Plot the convergence graph
plot(numElmnts, abs(tipDeflection(:, 1)), "-bo", LineWidth=2); %[output:2c6fb702]
hold on; %[output:2c6fb702]
plot(numElmnts, abs(tipDeflection(:, 2)), "-bv", LineWidth=2); %[output:2c6fb702]
plot(numElmnts, abs(tipDeflection(:, 3)), "-ro", LineWidth=2); %[output:2c6fb702]
plot(numElmnts, abs(tipDeflection(:, 4)), "-m^", LineWidth=2); %[output:2c6fb702]
plot(numElmnts, abs(tipDeflection(:, 5)), "-go", LineWidth=2); %[output:2c6fb702]
plot(numElmnts, abs(tipDeflectionAnalytical), "-k", LineWidth=2); %[output:2c6fb702]
hold off; %[output:2c6fb702]
grid on; %[output:2c6fb702]
legend("L1", "L1 reduced", "L2", "L" + num2str(choiceShapeFunctionsU) + ... %[output:2c6fb702]
    '/' + num2str(choiceShapeFunctionsLM) + " H/R", "E/B", "Analytical", ... %[output:2c6fb702]
    Location="best") %[output:2c6fb702]
xlabel("No. elements") %[output:2c6fb702]
ylabel("$w (x = L)$", "Interpreter","latex") %[output:2c6fb702]
title("Convergence study") %[output:2c6fb702]
%[text] ![](text:image:5384) **Try**
